%[text] # Gaussian Process Regression: First Applied Demo
%[text] This is a self-contained MATLAB script for teaching Gaussian Process (GP) regression in an applied, first-exposure way.
%[text] It can be run as a normal MATLAB script. It is also organized with %% sections, so it can be opened in the MATLAB Live Editor and saved as a Live Script (.mlx) if desired.
%[text] Main idea:
%[text]{"align":"center"} $\\text{A Gaussian Process gives a prediction and an uncertainty band.}$
%[text] This file uses no toolbox-specific GP functions. Everything is implemented from scratch using a kernel matrix and Cholesky factorization.
clear; clc; close all;
%%\

% Make all plot text LaTeX-compatible.
set(groot, 'defaultTextInterpreter', 'latex');
set(groot, 'defaultAxesTickLabelInterpreter', 'latex');
set(groot, 'defaultLegendInterpreter', 'latex');
set(groot, 'defaultAxesFontSize', 18);
set(groot, 'defaultLineLineWidth', 2);
%%
%[text] ## 1. Create Some Data
%[text] We create synthetic noisy measurements from a smooth function.
%[text] In a real application, these could be:
%[text] - lift coefficient versus angle of attack
%[text] - stress versus geometry parameter
%[text] - temperature versus location
%[text] - drug release versus time
%[text] - manufacturing defect rate versus process setting \
%[text] The GP does not know the true function. It only sees the noisy data.
%[text] The measurement model is:
%[text]{"align":"center"} $y\_i = f(x\_i) + \\varepsilon\_i, \\qquad \\varepsilon\_i \\sim \\mathcal{N}(0,\\sigma\_n^2).$
rng(2);  % for reproducibility

% Training input locations
X = [-4.5; -3.8; -3.1; -2.0; -1.2; -0.4; 0.7; 1.3; 2.1; 3.0; 3.8; 4.5];

% True function, used only to generate data and for teaching comparison
ftrue = @(x) sin(1.2*x) + 0.25*x;

% Noisy measurements
noise_std_true = 0.25;
y = ftrue(X) + noise_std_true*randn(size(X));

% Test locations where we want predictions
Xtest = linspace(-6, 6, 300)';

figure('Color','w'); hold on; box on; %[output:41c67fe7]
scatter(X, y, 70, 'filled'); %[output:41c67fe7]
xlabel('$x$'); %[output:41c67fe7]
ylabel('$y$'); %[output:41c67fe7]
title('Training Data: Noisy Samples of an Unknown Function'); %[output:41c67fe7]
set(gca, 'FontSize', 18); %[output:41c67fe7]
grid on; %[output:41c67fe7]
%%
%[text] ## 2. Choose the Kernel
%[text] A GP needs a kernel.
%[text] The kernel tells us how strongly two input points are related.
%[text] Here we use the radial basis function (RBF) kernel:
%[text]{"align":"center"} $k(x\_i,x\_j) = \\sigma\_f^2\n \\exp\\left\[-\\frac{(x\_i-x\_j)^2}{2\\ell^2}\\right\].$
%[text] The most important parameter is $\\ell$, the length scale.
%[text] - small $\\ell$ $\\rightarrow$ wiggly function
%[text] - large $\\ell$ $\\rightarrow$ smoother function \
%[text] The signal scale $\\sigma\_f$ controls vertical variation.
%[text] The noise parameter $\\sigma\_n$ controls how much we trust the measured data.
ell = 1.2;     % length scale
sf  = 1.0;     % signal standard deviation
sn  = 0.25;    % assumed measurement noise standard deviation
%%
%[text] ## 3. Plot the Kernel Shape
%[text] The kernel can be viewed as an influence function centered at one point.
%[text] If the reference point is $x\_0=0$, then the curve
%[text]{"align":"center"} $k(x,x\_0)$
%[text] shows how strongly another point $x$ is related to $x\_0$.
%[text] Nearby points have large covariance. Far-away points have small covariance.
x0 = 0;
xKernel = linspace(-5, 5, 400)';
ell_values = [0.5, ell, 2.5];

figure('Color','w'); hold on; box on; %[output:311db31f]
for q = 1:numel(ell_values)
    kCurve = rbfKernel(xKernel, x0, ell_values(q), sf);
    plot(xKernel, kCurve, 'DisplayName', sprintf('$\\ell = %.1f$', ell_values(q))); %[output:311db31f]
end
xline(x0, '--', '$x_0$', 'LabelVerticalAlignment', 'bottom', 'Interpreter', 'latex'); %[output:311db31f]
xlabel('$x$'); %[output:311db31f]
ylabel('$k(x,x_0)$'); %[output:311db31f]
title('RBF Kernel as a Similarity Function'); %[output:311db31f]
legend('Location', 'northeast'); %[output:311db31f]
grid on; %[output:311db31f]
set(gca, 'FontSize', 18); %[output:311db31f]
%%
%[text] ## 4. Build Covariance Matrices
%[text] The covariance matrices are similarity tables.
%[text] Training-to-training covariance:
%[text]{"align":"center"} $K(X,X)\_{ij}=k(x\_i,x\_j).$
%[text] This is an $n\\times n$ table that answers:
%[text]{"align":"center"} $\\text{How related are training point }x\_i\\text{ and training point }x\_j\\text{?}$
%[text] Training-to-test covariance:
%[text]{"align":"center"} $K(X,X\_\*)\_{ij}=k(x\_i,x^\*\_j).$
%[text] This answers:
%[text]{"align":"center"} $\\text{How much should training point }x\_i\\text{ influence prediction point }x^\*\_j\\text{?}$
%[text] Test-to-test covariance:
%[text]{"align":"center"} $K(X\_\*,X\_\*)\_{ij}=k(x^\*\_i,x^\*\_j).$
%[text] This is needed for the uncertainty band.
K   = rbfKernel(X, X, ell, sf);          % training-to-training covariance
Ks  = rbfKernel(X, Xtest, ell, sf);      % training-to-test covariance
Kss = rbfKernel(Xtest, Xtest, ell, sf);  % test-to-test covariance

% Add measurement noise only to the training covariance.
%
% $$K_y = K(X,X) + \sigma_n^2 I.$$
%
% This says: the observations are noisy, so the GP should not be forced to
% pass exactly through every measured point.
Ky = K + sn^2 * eye(length(X));
%%
%[text] ## 5. Plot the Training Similarity Matrix
%[text] The matrix $K(X,X)$ is the assembled similarity matrix for the training data. Entry $K\_{ij}$ is bright/large when $x\_i$ and $x\_j$ are close.
%[text] The diagonal is largest because every point is perfectly similar to itself:
%[text]{"align":"center"} $K\_{ii}=k(x\_i,x\_i)=\\sigma\_f^2.$
figure('Color','w'); %[output:22688438]
imagesc(K); %[output:22688438]
axis image; %[output:22688438]
colormap(parula); %[output:22688438]
cb = colorbar; %[output:22688438]
cb.Label.String = '$K_{ij}$'; %[output:22688438]
cb.Label.Interpreter = 'latex'; %[output:22688438]
cb.TickLabelInterpreter = 'latex'; %[output:22688438]
xlabel('Training point index $j$'); %[output:22688438]
ylabel('Training point index $i$'); %[output:22688438]
title('Assembled Similarity Matrix $K(X,X)$'); %[output:22688438]
set(gca, 'FontSize', 18); %[output:22688438]
set(gca, 'XTick', 1:length(X), 'YTick', 1:length(X)); %[output:22688438]
%%
%[text] ## 6. Solve for the Influence Weights
%[text] The GP mean can be written as:
%[text]{"align":"center"} $\\mu(x) = \\sum\_{i=1}^{n}\\alpha\_i k(x,x\_i).$
%[text] This means the GP prediction is a weighted sum of kernel functions centered at the training points.
%[text] The vector $\\alpha$ contains the learned influence weights.
%[text] Mathematically:
%[text]{"align":"center"} $\\alpha = K\_y^{-1}y.$
%[text] In code, we do not compute $K\_y^{-1}$. Instead, we solve:
%[text]{"align":"center"} $K\_y\\alpha = y$
%[text] using Cholesky factorization.
%[text] Since $K\_y$ is symmetric positive definite, Cholesky gives:
%[text]{"align":"center"} $K\_y = LL^T.$
L = chol(Ky, 'lower');

% Solve the two triangular systems:
%
% $$Lz = y,$$
%
% $$L^T\alpha = z.$$
%
% This gives $\alpha = K_y \backslash y$ without directly inverting $K_y$.
alpha = L' \ (L \ y);
%%
%[text] ## 7. Predict the GP Mean
%[text] To predict at a new point, the GP asks:
%[text]{"align":"center"} $\\text{How similar is this new point to each training point?}$
%[text] Then it blends the learned weights $\\alpha$ using those similarities.
%[text] For all test points:
%[text]{"align":"center"} $\\mu\_\* = K(X,X\_\*)^T\\alpha.$
mu = Ks' * alpha;
%%
%[text] ## 8. Predict the GP Uncertainty
%[text] The GP also gives an uncertainty estimate.
%[text] Applied interpretation:
%[text] - near data: lower uncertainty
%[text] - far from data: higher uncertainty
%[text] - noisy data: uncertainty does not collapse completely \
%[text] The predictive covariance is:
%[text]{"align":"center"} $\\Sigma\_\* = K(X\_\*,X\_\*) - K(X,X\_\*)^T K\_y^{-1} K(X,X\_\*).$
%[text] Again, we do not compute $K\_y^{-1}$. We reuse the Cholesky factor.
v = L \ Ks;
Sigma = Kss - v' * v;

% Numerical cleanup: tiny negative values may appear on the diagonal due to
% floating-point roundoff.
var_gp = max(diag(Sigma), 0);
std_gp = sqrt(var_gp);
%%
%[text] ## 9. Plot the Final GP Result
%[text] The uncertainty band shown here is:
%[text]{"align":"center"} $\\mu\_\* \\pm 2\\sigma\_\*.$
%[text] For a Gaussian distribution, this is often interpreted as an approximate 95 percent uncertainty band.
figure('Color','w'); hold on; box on; %[output:1804d8b1]

% Uncertainty band: mean +/- 2 standard deviations
x_fill = [Xtest; flipud(Xtest)];
y_fill = [mu + 2*std_gp; flipud(mu - 2*std_gp)];

fill(x_fill, y_fill, [0.85 0.85 0.85], ... %[output:1804d8b1]
    'EdgeColor', 'none', ... %[output:1804d8b1]
    'FaceAlpha', 0.8, ... %[output:1804d8b1]
    'DisplayName', '$\mu_* \pm 2\sigma_*$'); %[output:1804d8b1]

% GP mean
plot(Xtest, mu, 'k-', 'LineWidth', 2.5, 'DisplayName', 'GP mean $\mu_*$'); %[output:1804d8b1]

% Training data
scatter(X, y, 70, 'filled', 'DisplayName', 'Training data'); %[output:1804d8b1]

% True function for teaching comparison only
plot(Xtest, ftrue(Xtest), 'r--', 'LineWidth', 2, 'DisplayName', 'True function'); %[output:1804d8b1]

xlabel('$x$'); %[output:1804d8b1]
ylabel('$y$'); %[output:1804d8b1]
title('Gaussian Process Regression'); %[output:1804d8b1]
legend('Location', 'northwest'); %[output:1804d8b1]
set(gca, 'FontSize', 18); %[output:1804d8b1]
grid on; %[output:1804d8b1]
%%
%[text] ## 10. Main Takeaways
%[text]{"align":"center"} A Gaussian Process regression model needs four practical ingredients:$\\text{data} + \\text{kernel} + \\text{noise level} + \\text{linear solve}$
%[text] The kernel defines smoothness.
%[text] The noise level controls how much we trust the data.
%[text] The linear solve finds the influence weights.
%[text] The output is a prediction with uncertainty.
disp('Done.'); %[output:59eeb32d]
disp('Key idea: a GP gives a prediction and an uncertainty band.'); %[output:9d9682a5]
%%
%[text] ## Local Function: RBF Kernel
function K = rbfKernel(X1, X2, ell, sf)
%RBFKERNEL Squared exponential / radial basis function kernel.
%
% $$K_{ij}=\sigma_f^2\exp\left[-\frac{(X_{1,i}-X_{2,j})^2}{2\ell^2}\right].$$
%
% Inputs:
%   X1  - first set of input points, n x 1
%   X2  - second set of input points, m x 1
%   ell - length scale
%   sf  - signal standard deviation
%
% Output:
%   K   - covariance matrix, n x m

    D2 = (X1 - X2').^2;
    K = sf^2 * exp(-0.5 * D2 / ell^2);

end

